// Small hand-written 8N1 serial adapter for the C#-generated byte controller.
// DIVISOR = round(clock_hz / baud). Require DIVISOR >= 8.
// One receive holding register; host must use stop-and-wait commands.
module debug_uart_serial #(parameter integer DIVISOR=434)(
    input wire clk,input wire rst,input wire uart_rx,output wire uart_tx,
    output wire [7:0] control_out,output wire [31:0] counter_out,
    output reg rx_overrun,output reg framing_error
);
    reg rx_meta,rx_sync;
    always @(posedge clk) begin
        if(rst) begin rx_meta<=1;rx_sync<=1;end
        else begin rx_meta<=uart_rx;rx_sync<=rx_meta;end
    end
    reg [1:0] rx_state;
    reg [31:0] rx_timer;
    reg [2:0] rx_bit;
    reg [7:0] rx_shift,rx_data;
    reg rx_valid;
    wire rx_ready;
    always @(posedge clk) begin
        if(rst) begin
            rx_state<=0;rx_timer<=0;rx_bit<=0;rx_shift<=0;
            rx_data<=0;rx_valid<=0;rx_overrun<=0;framing_error<=0;
        end else begin
            if(rx_valid && rx_ready) rx_valid<=0;
            case(rx_state)
                0: if(!rx_sync) begin rx_state<=1;rx_timer<=DIVISOR/2-1;end
                1: if(rx_timer!=0) rx_timer<=rx_timer-1;
                   else if(!rx_sync) begin rx_state<=2;rx_bit<=0;rx_timer<=DIVISOR-1;end
                   else rx_state<=0;
                2: if(rx_timer!=0) rx_timer<=rx_timer-1;
                   else begin
                       rx_shift[rx_bit]<=rx_sync;rx_timer<=DIVISOR-1;
                       if(rx_bit==7)rx_state<=3;else rx_bit<=rx_bit+1'b1;
                   end
                3: if(rx_timer!=0)rx_timer<=rx_timer-1;
                   else begin
                       rx_state<=0;
                       if(!rx_sync)framing_error<=1;
                       else if(!rx_valid || rx_ready)begin rx_data<=rx_shift;rx_valid<=1;end
                       else rx_overrun<=1;
                   end
            endcase
        end
    end

    wire [7:0] tx_data,tx_user;
    wire tx_valid,tx_keep,tx_last;
    reg tx_busy;
    reg [9:0] tx_shift;
    reg [31:0] tx_timer;
    reg [3:0] tx_bit;
    wire tx_ready=!tx_busy;
    assign uart_tx=tx_busy ? tx_shift[0] : 1'b1;
    always @(posedge clk) begin
        if(rst)begin tx_busy<=0;tx_shift<=10'h3ff;tx_timer<=0;tx_bit<=0;end
        else if(!tx_busy)begin
            if(tx_valid)begin tx_busy<=1;tx_shift<={1'b1,tx_data,1'b0};tx_timer<=DIVISOR-1;tx_bit<=0;end
        end else if(tx_timer!=0)tx_timer<=tx_timer-1;
        else begin
            tx_timer<=DIVISOR-1;tx_shift<={1'b1,tx_shift[9:1]};
            if(tx_bit==9)tx_busy<=0;else tx_bit<=tx_bit+1'b1;
        end
    end
    h_DebugUartController controller (
        .clk(clk),.rst(rst),
        .s_rx_tdata(rx_data),.s_rx_tkeep(1'b1),.s_rx_tlast(1'b1),.s_rx_tuser(8'd0),
        .s_rx_tvalid(rx_valid),.s_rx_tready(rx_ready),
        .s_tx_tdata(tx_data),.s_tx_tkeep(tx_keep),.s_tx_tlast(tx_last),.s_tx_tuser(tx_user),
        .s_tx_tvalid(tx_valid),.s_tx_tready(tx_ready),
        .s_control_out(control_out),.s_counter_out(counter_out));
endmodule
